// ============================================================================
// Stage Card Swipe (Left/Right) & Below-Card Blank Zone Double-Tap Undo
// ============================================================================
(function initStageGestures() {
  let touchStartX = 0;
  let touchStartY = 0;
  let touchStartTime = 0;
  let swipeEligible = false;

  document.addEventListener("touchstart", e => {
    if (viewMode !== "stage" || (window.__subject && window.__subject !== "en")) return;
    if (!e.touches || e.touches.length !== 1) {
      swipeEligible = false;
      return;
    }
    if (document.body.classList.contains("nav-open")) {
      swipeEligible = false;
      return;
    }
    const modal = document.getElementById("fsrs-modal");
    if (modal && modal.classList.contains("show")) {
      swipeEligible = false;
      return;
    }
    const t = e.target;
    const inExcluded = t && t.closest ? t.closest(".topbar, .today-strip, .app-side, .stage-dock, .stage-flip-prompt, .stage-nav, .modal-backdrop, .pack-popover, button, input, textarea, select, a") : null;
    if (!inExcluded) {
      swipeEligible = true;
      touchStartX = e.touches[0].clientX;
      touchStartY = e.touches[0].clientY;
      touchStartTime = Date.now();
    } else {
      swipeEligible = false;
    }
  }, { passive: true });

  document.addEventListener("touchend", e => {
    if (!swipeEligible || viewMode !== "stage") return;
    swipeEligible = false;
    if (!e.changedTouches || e.changedTouches.length !== 1) return;
    const dx = e.changedTouches[0].clientX - touchStartX;
    const dy = e.changedTouches[0].clientY - touchStartY;
    const dt = Date.now() - touchStartTime;
    if (dt < 700 && Math.abs(dx) > 36 && Math.abs(dx) > Math.abs(dy) * 1.35) {
      if (dx < 0) stepStageCard(1);
      else openSubjectNav();
    }
  }, { passive: true });

  // Double-tap / double-click strictly in the blank space BELOW .stage-card
  let lastBlankTapTs = 0;
  let lastBlankTapX = 0;
  let lastBlankTapY = 0;

  function isBelowCardBlankArea(target, clientY) {
    if (viewMode !== "stage" || (window.__subject && window.__subject !== "en")) return false;
    if (document.body.classList.contains("nav-open")) return false;
    const modal = document.getElementById("fsrs-modal");
    if (modal && modal.classList.contains("show")) return false;
    if (!target || !target.closest) return false;
    if (target.closest(".stage-dock, .stage-flip-prompt, .stage-nav, .pack-popover, .topbar, .app-side, button, a, input")) {
      return false;
    }
    if (target.id === "stage-blank-undo-zone") return true;
    const cardEl = document.querySelector("#stage-container .stage-card");
    if (!cardEl) return false;
    const rect = cardEl.getBoundingClientRect();
    return clientY > rect.bottom + 4;
  }

  function triggerBlankUndo() {
    if (undoStack.length === 0) {
      showToast("当前暂无可撤销的打分记录");
      return;
    }
    undoLastRating();
  }

  document.addEventListener("touchend", e => {
    if (!e.changedTouches || e.changedTouches.length !== 1) return;
    const touch = e.changedTouches[0];
    if (!isBelowCardBlankArea(e.target, touch.clientY)) {
      lastBlankTapTs = 0;
      return;
    }
    const now = Date.now();
    const dist = Math.hypot(touch.clientX - lastBlankTapX, touch.clientY - lastBlankTapY);
    if (now - lastBlankTapTs < 340 && dist < 48) {
      lastBlankTapTs = 0;
      if (e.cancelable) e.preventDefault();
      triggerBlankUndo();
    } else {
      lastBlankTapTs = now;
      lastBlankTapX = touch.clientX;
      lastBlankTapY = touch.clientY;
    }
  }, { passive: false });

  document.addEventListener("dblclick", e => {
    if (isBelowCardBlankArea(e.target, e.clientY)) {
      e.preventDefault();
      triggerBlankUndo();
    }
  });
})();

document.addEventListener("click", e => {
  if (!document.body.classList.contains("nav-open")) return;
  if (e.target && e.target.isConnected === false) return;
  const nav = document.getElementById("subject-nav");
  if (nav && nav.contains(e.target)) return;
  closeSubjectNav();
});

document.addEventListener("keydown", e => {
  const t = e.target;
  if (e.key === "Escape") {
    closeSubjectNav();
    if (window.Core && Core.closeMore) Core.closeMore();
    if (t && (t.id === "search-box" || t.id === "m-search" || t.id === "tree-search")) { t.blur(); if (window.Core && Core.closeSearch) Core.closeSearch(); }
    return;
  }
  if ((e.metaKey || e.ctrlKey) && !e.altKey && !e.shiftKey && e.key.toLowerCase() === "f") {
    if (document.querySelector(".modal-backdrop.show")) return;
    e.preventDefault();
    if (window.Core && Core.openSearch) Core.openSearch();
    return;
  }
  if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.tagName === "SELECT")) return;
  if (e.key === "/" && !e.ctrlKey && !e.metaKey && !e.altKey) {
    if (document.querySelector(".modal-backdrop.show")) return;
    e.preventDefault();
    if (window.Core && Core.openSearch) Core.openSearch();
  }
});

