// Topbar Gemini-style progressive blur: only activate backdrop blur when page is actually scrolled
(function() {
  function syncTopbarScrollState() {
    const y = window.scrollY || window.pageYOffset || document.documentElement.scrollTop || 0;
    if (document.body) {
      document.body.classList.toggle("is-scrolled", y > 4);
    }
  }
  window.addEventListener("scroll", syncTopbarScrollState, { passive: true });
  window.addEventListener("touchmove", syncTopbarScrollState, { passive: true });
  window.addEventListener("resize", syncTopbarScrollState, { passive: true });
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", syncTopbarScrollState);
  } else {
    syncTopbarScrollState();
  }
})();
